-- Empty explicit tenant configuration grants; metadata ownership grants no record access.
CREATE TABLE IF NOT EXISTS hs_data_tenant_grants(tenant_id uuid NOT NULL REFERENCES hs_data_tenants(id),user_id text NOT NULL REFERENCES hs_users(id),capabilities text[] NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1,CHECK(capabilities <@ ARRAY['manage-collections']::text[]),PRIMARY KEY(tenant_id,user_id));
ALTER TABLE hs_data_collections ADD COLUMN IF NOT EXISTS name_search text GENERATED ALWAYS AS(lower(name)) STORED;
CREATE UNIQUE INDEX IF NOT EXISTS hs_data_collection_unique_name ON hs_data_collections(tenant_id,name_search);
CREATE TABLE IF NOT EXISTS hs_data_collection_settings(tenant_id uuid NOT NULL,collection text NOT NULL,description text NOT NULL DEFAULT '',owner_id text NOT NULL REFERENCES hs_users(id),created_by text NOT NULL REFERENCES hs_users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),removed_at timestamptz,PRIMARY KEY(tenant_id,collection),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_collection_versions(tenant_id uuid NOT NULL,collection text NOT NULL,version integer NOT NULL,definition jsonb NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,collection,version),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_collection_operations(tenant_id uuid NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,request_hash text NOT NULL,collection text NOT NULL,applied_version integer NOT NULL,kind text NOT NULL,PRIMARY KEY(tenant_id,actor_id,operation_id),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_collection_previews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,workspace_id text NOT NULL REFERENCES hs_workspaces(id),actor_id text NOT NULL REFERENCES hs_users(id),collection text NOT NULL,kind text NOT NULL,input_hash text NOT NULL,review_hash text NOT NULL,record_version integer NOT NULL,schema_version integer NOT NULL,authority_revision text NOT NULL,external_revision text,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '10 minutes');
CREATE TABLE IF NOT EXISTS hs_data_collection_consumers(tenant_id uuid NOT NULL,collection text NOT NULL,client_id text NOT NULL,resource_type text NOT NULL,resource_id text NOT NULL,version integer NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,collection,client_id,resource_type,resource_id),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
DROP TRIGGER IF EXISTS hs_data_collection_versions_immutable ON hs_data_collection_versions;
CREATE TRIGGER hs_data_collection_versions_immutable BEFORE UPDATE OR DELETE ON hs_data_collection_versions FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
CREATE OR REPLACE FUNCTION hs_data_collection_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.tenant_id<>OLD.tenant_id OR NEW.id<>OLD.id OR NEW.core<>OLD.core THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Collection identity and core status are immutable'; END IF;RETURN NEW;END $$;
DROP TRIGGER IF EXISTS hs_data_collection_identity_guard ON hs_data_collections;
CREATE TRIGGER hs_data_collection_identity_guard BEFORE UPDATE ON hs_data_collections FOR EACH ROW EXECUTE FUNCTION hs_data_collection_identity_guard();
